import sys
from collections import defaultdict

def count_valid_sets(N, V, edges):
    from functools import lru_cache

    # Build the tree
    tree = defaultdict(list)
    for A, B in edges:
        tree[A].append(B)

    @lru_cache(None)
    def dp(node, parent_jokes):
        if node == 1:
            return {frozenset([V[node-1]])}

        valid_sets = set()
        for child in tree[node]:
            child_sets = dp(child, frozenset(parent_jokes | {V[node-1]}))
            for child_set in child_sets:
                if len(child_set) == 0:
                    continue
                if V[node-1] not in child_set:
                    new_set = child_set | {V[node-1]}
                    if len(new_set) == 1 or max(new_set) - min(new_set) + 1 == len(new_set):
                        valid_sets.add(new_set)

        return valid_sets

    result = dp(1, frozenset())
    return len(result)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    index += 1
    V = list(map(int, data[index:index+N]))
    index += N
    edges = []
    for _ in range(N-1):
        A = int(data[index])
        B = int(data[index+1])
        edges.append((A, B))
        index += 2

    print(count_valid_sets(N, V, edges))

if __name__ == "__main__":
    main()
